   162	fn do_execve_no_return(
   163	    ctx: &Context,
   164	    user_context: &mut UserContext,
   165	    elf_file: Path,
   166	    thread_name: ThreadName,
   167	    new_vmar: VmarHandle,
   168	    elf_load_info: &ElfLoadInfo,
   169	    capsets_for_exec: ExecCapSets,
   170	) -> Result<()> {
   171	    let Context {
   172	        process,
   173	        thread_local,
   174	        posix_thread,
   175	        ..
   176	    } = ctx;
   177	
   178	    // Wait for all other threads to terminate,
   179	    // then promote the current thread to be the process's main thread if necessary.
   180	    wait_other_threads_exit(ctx)?;
   181	    make_current_main_thread(ctx);
   182	
   183	    // Activate the new VMAR in the current context and apply file-capability changes,
   184	    // while holding the process VMAR lock.
   185	    // This prevents race conditions when checking access permissions while opening
   186	    // `/proc/[pid]/mem` or `/proc/[pid]/maps`.
   187	    let (vmar_guard, old_vmar) = activate_vmar(ctx, new_vmar);
   188	    let credentials = ctx.credentials_mut();
   189	    apply_caps_from_exec(process, &credentials, elf_file.inode(), capsets_for_exec)?;
   190	    drop(vmar_guard);
   191	    drop(old_vmar);
   192	
   193	    // After the program has been successfully loaded, the virtual memory of the current process
   194	    // is initialized. Hence, it is necessary to clear the previously recorded robust list.
   195	    *thread_local.robust_list().borrow_mut() = None;
   196	    thread_local.clear_child_tid().set(0);
   197	
   198	    // Set up the CPU context.
   199	    set_cpu_context(thread_local, user_context, elf_load_info);
   200	
   201	    // If this was a vfork child, reset vfork-specific state.
   202	    reset_vfork_child(process);
   203	
   204	    // Unshare file descriptor table and close files with O_CLOEXEC flag.
   205	    unshare_and_close_files(ctx);
   206	
   207	    // Set the thread name.
   208	    *posix_thread.thread_name().lock() = thread_name;
   209	
   210	    // Unshare and reset signal dispositions to their default actions.
   211	    unshare_and_reset_sigdispositions(process);
   212	    // Reset the alternate signal stack to its default state.
   213	    *thread_local.sig_stack().borrow_mut() = SigStack::default();
   214	    // Restore the process exit signal to SIGCHLD.
   215	    process.set_exit_signal(SIGCHLD);
   216	
   217	    Ok(())
   218	}
